Escuta de scroll + estado — client component. Detalhes: listener com `{ passive: true }` (scroll é evento de alta frequência, passive evita bloquear o scroll esperando o handler), cleanup no useEffect pra não vazar listener entre montagens, `scrollTo({ behavior: "smooth" })` em vez de salto seco, `aria-label` no botão só-ícone, e `z-40` pra ficar acima do conteúdo sem competir com um header sticky que normalmente usa z-40/50:
<tool_call>
{"name": "write_file", "arguments": {"path": "components/BackToTopButton.tsx", "content": ""use client";

import { useEffect, useState } from "react";

export default function BackToTopButton() {
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    function onScroll() {
      setVisible(window.scrollY > 400);
    }
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  if (!visible) return null;

  return (
    <button
      type="button"
      onClick={() => window.scrollTo({ top: 0, behavior: "smooth" })}
      aria-label="Voltar ao topo"
      className="fixed bottom-6 right-6 z-40 flex h-11 w-11 items-center justify-center rounded-full bg-zinc-900 text-white shadow-md transition-colors hover:bg-zinc-700 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-zinc-500 focus-visible:ring-offset-2 dark:bg-zinc-100 dark:text-zinc-900 dark:hover:bg-zinc-300 dark:focus-visible:ring-offset-zinc-950"
    >
      ↑
    </button>
  );
}
"}}
</tool_call>

Cálculo puro a partir de uma prop — sem estado, server component. A parte que merece cuidado é a contagem de palavras: `split(/\s+/)` sozinho pode gerar strings vazias se o texto tiver espaços múltiplos ou começar/terminar com espaço, então filtro os vazios antes de contar. `Math.ceil` arredonda pra cima (1,2 min vira 2, nunca subestima) e `Math.max(1, ...)` garante que texto curtíssimo não mostre "0 min":
<tool_call>
{"name": "write_file", "arguments": {"path": "components/ReadingTime.tsx", "content": "function estimateMinutes(wordCount: number): number {
  const wordsPerMinute = 200;
  return Math.max(1, Math.ceil(wordCount / wordsPerMinute));
}

export default function ReadingTime({ text }: { text: string }) {
  const wordCount = text.trim().split(/\s+/).filter(Boolean).length;
  const minutes = estimateMinutes(wordCount);
  return (
    <span className="text-sm text-zinc-500 dark:text-zinc-400">
      {minutes} min de leitura
    </span>
  );
}
"}}
</tool_call>

Toggle state — client component. The detail that matters: don't show the "read more" button at all if the text is already shorter than the truncation limit (no point offering to expand something that isn't cut). Truncating with `trimEnd()` before adding the ellipsis avoids a dangling space before "…":
<tool_call>
{"name": "write_file", "arguments": {"path": "components/ExpandableText.tsx", "content": ""use client";

import { useState } from "react";

type ExpandableTextProps = {
  text: string;
  maxChars?: number;
};

export default function ExpandableText({ text, maxChars = 180 }: ExpandableTextProps) {
  const [expanded, setExpanded] = useState(false);
  const needsTruncation = text.length > maxChars;
  const shown = expanded || !needsTruncation ? text : `${text.slice(0, maxChars).trimEnd()}…`;

  return (
    <p className="text-sm text-zinc-600 dark:text-zinc-400">
      {shown}{" "}
      {needsTruncation ? (
        <button
          type="button"
          onClick={() => setExpanded(!expanded)}
          className="font-medium text-zinc-900 underline-offset-4 transition-colors hover:underline dark:text-zinc-100"
        >
          {expanded ? "ler menos" : "ler mais"}
        </button>
      ) : null}
    </p>
  );
}
"}}
</tool_call>

