1	export default function TimestampBadge({ isoDate }: { isoDate: string }) {
2	  return <span>{isoDate}</span>;
3	}

Confirmado — exibe a string ISO sem tratamento nenhum. 4 correções:
1. o pedido central: texto relativo ("há 5 min", "há 2h", "há 3d") em vez da ISO crua;
2. mas a data completa não deve DESAPARECER — só fica em `title`, pro hover nativo mostrar a data exata quando alguém precisar (informação relativa perde precisão de propósito, o `title` recupera isso sob demanda);
3. elemento semântico `<time dateTime={isoDate}>` em vez de `<span>` — acessibilidade e SEO ganham a data máquina-legível junto com o texto humano;
4. cor rebaixada (`zinc-400`/`zinc-500`) — timestamp é sempre informação secundária.
Aplicando:
<tool_call>
{"name": "write_file", "arguments": {"path": "components/TimestampBadge.tsx", "content": "function timeAgo(isoDate: string): string {
  const diffMs = Date.now() - new Date(isoDate).getTime();
  const minutes = Math.floor(diffMs / 60000);
  if (minutes < 1) return "agora mesmo";
  if (minutes < 60) return `há ${minutes} min`;
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return `há ${hours}h`;
  const days = Math.floor(hours / 24);
  return `há ${days}d`;
}

export default function TimestampBadge({ isoDate }: { isoDate: string }) {
  return (
    <time
      dateTime={isoDate}
      title={new Date(isoDate).toLocaleString("pt-BR")}
      className="text-xs text-zinc-400 dark:text-zinc-500"
    >
      {timeAgo(isoDate)}
    </time>
  );
}
"}}
</tool_call>

